    dimensions: { height: 10.9, width: 5.6 },
    description: 'This finely carved two-color 漆 tea bowl bears an inscription of a poem composed by 皇帝 Qianlong in 1746. The poem praises the “three purity tea” (sanqing cha), which consists of plum blossom petals, fingered citron and pine nuts, and must be brewed in melted snow water. According to 皇家 records, 皇帝 Qianlong often served sanqing tea during his renowned tea gatherings held in the 宫殿 during the New Year season. It was at one of these banquets that he wrote this poem. Although the same poem appears on many tea utensils made for the 皇帝, 漆 pieces like this bowl are particularly rare due to the extensive time and effort required for their production.',
