    description: '中国 瓷 made especially for export to the United States often displays painted imagery of subjects that appealed to wealthy American consumers, including armorials and marine scenes and commemorations of importnat events. Part of a larger suite, these four pieces were commissioned around 1800 in remembrance of the nation’s first president who died in 1799. Symbols such as the weeping willow, tomb, and eagle, all depicted on these wares, reflect the contemporary mourning for Washington.',
