    category: '宗教礼器',
    material: '青铜',
    dimensions: { height: 41.7, width: 28.9 },
    description: 'Bells of this type are among China\'s earliest percussion instruments. Many have been unearthed from 山 slopes and along riverbanks in south China. This area was occupied by distinctive cultures that coexisted with the Shang and Western Zhou dynasties. Along this southern frontier, it appears that large 青铜 bells were more important than 青铜 vessels to the local aristocracy.This bell was designed to be mounted on its hollow stem with its curved mouth facing up and struck from the outside with a mallet. Unlike other types of 青铜 bells that were assembled as chime sets, this one was intended to be played as an individual instrument. It may have been sounded during ceremonies or military campaigns. The eyebrow-shaped lines that skim the margins of this bell depict imaginary dragons or realistic reptiles.',
    history: 'Bells of this type are among China\'s earliest percussion instruments。来源: Lucy Maud Buckingham Collection',
