    material: 'Limestone镶嵌微量polychromy',
    dimensions: { height: 157.5, width: 80.6 },
    description: 'In eighth-century China, 佛教 sculptors adopted new standards of secular beauty for spiritual figures. Whereas images of the Buddha appear sternly formal, bodhisattvas, the merciful deities that guide men toward salvation, often display more humanistic features. This bodhisattva\'s graceful proportions, upswept hair, sinuous drapery, and delicate jewelry convey an appealing physical elegance. Seated informally, the deity is poised to step down from its pedestal.Together with a large seated Buddha and another attendant bodhisattva in the Art Institute collection (1930.83, 1930.84), this sculpture came to the museum in 1930 with a note of its discovery in a 寺庙 known as Cangfosi in northern Hebei province. Neither archaeological nor written records have been located to confirm this reported site. The scale and stone medium of these figures suggest that they were commissioned for a cave 寺庙 or shrine a chamber carved into the face of a 山 or cliff.',
