    id: '76279',
    name: 'Yang Pu Moving His Family',
    nameEn: 'Yang Pu Moving His Family',
    era: '元朝 (1279–1368年)',
    region: '中国绘画',
    category: '绘画',
    material: 'Handscroll，墨与lightcolor纸',
    dimensions: { height: 231.1, width: 52.7 },
    description: 'This detail of a scroll painting depicts a village scholar (at left ) bidding farewell to his friends while transporting his family across a narrow 河. Distinguished by his official government cap with its long streamers, he is accompanied by servants who valiantly attempt to carry his children and the family’s belongings, which include scrolls, animals, and dishes. The rustic figure shown here may represent Yang Pu, a character who appears in twelfth- and thirteenth-century stories. As described in this folklore, Yang initially declined, and then reluctantly accepted, his appointment to a government position in the capital. In an attempt to prevent sectionalism and corruption, 中国 law forbade civil officials from working in their native districts, and many were required to move to distant cities. Given China’s vastness, it was unlikely that these men, once transferred, would ever see their friends again. Such partings were frequent and often somber occasions and a favorite theme of poets and painters. The twigs that protrude from the official caps of the men depicted here may allude to the ancient 中国 custom of presenting departing friends with small branches from a willow tree. In this painting, however, the “noble parting” theme has been reinterpreted with a lively combination of realism and caricature.',
    history: 'This detail of a scroll painting depicts a village scholar (at left ) bidding farewell to his friends while transporting his family across a narrow river。来源: Kate S. Buckingham Endowment',
