    material: '鎏金铜合金镶嵌微量颜料(青金石lazuli)',
    dimensions: { height: 21.5, width: 13.5, depth: 12.5 },
    description: 'China\'s pantheon of 佛教 deities, with their accompanying rituals and artistic styles, burgeoned following its conquest by the Mongols and its absorption into the pan-Asian, multiethnic Yuan empire (1279 1368). From then on, many 中国 rulers and members of elite society, of both native and foreign heritage, became fervent devotees of Tibetan Buddhism. This faith is also known as Vajrayana (Diamond Path) Buddhism or, for its esoteric teachings derived largely from Hinduism, Tantric Buddhism. 佛教 images made in China but influenced by Tibetan (as well as Nepalese) iconography and style are termed Sino-Tibetan.This image depicts one of many emanations of the compassionate god Tara. An inscription on the top surface of its throne reads "Da Ming Yongle nian zhi" (Bestowed in the Yongle reign of the Great Ming). The Yongle 皇帝 was the third ruler of the Ming 朝代 and a great patron of 佛教 art.',
    history: 'China\'s pantheon of Buddhist deities, with their accompanying rituals and artistic styles, burgeoned following its conquest by the Mongols and its absorption into the pan-Asian, multiethnic Yuan empire (1279 1368)。来源: Gift of Guy H. Mitchell',
