    category: '建筑图纸',
    material: 'Graphite与coloredpencil纸',
    dimensions: { height: 45.5, width: 30.5 },
    description: 'The Kam L. Liu Center in the Chinatown neighborhood of Chicago serves the community with a focus on health, education, and social support. When approached to submit a design for the new center, Jeanne Gang found subtle ways to incorporate welcoming traditional 中国 colors and signs within a modern, airy space. The small construction budget did not limit the expressive qualities of the building, including a richly detailed lattice sunscreen and shimmering titanium shingles cladding the exterior. The identity of the building is defined by the diversity of its users, and the flexibility of programming in many of the interior spaces promotes intergenerational and international communication.',
    history: 'The Kam L。来源: Gift of Jeanne Gang',
    images: ['https://www.artic.edu/iiif/2/5f32d5f0-3548-1059-f91c-3f94f0f35db3/full/400,/0/default.jpg'],
    museum: '芝加哥艺术博物馆',
    location: '美国芝加哥',
