    dimensions: { height: 21.3, width: 19.4 },
    description: 'During the Han 朝代, fantastical beliefs in immortality and exotic lands inspired the earliest three-dimensional landscapes. The conical lid of this incense burner, shaped like towering peaks, is associated with the mountainous Isles of the Blessed. These islands were described as the realm of immortal beings (xian) in the myth, superstition, and magic widespread in Han 朝代 Religion. Fragrant smoke wafting through holes in the lid of this incense burner would evoke such a mist-shrouded utopia.',
