    name: 'Buddhist Votive Stele',
    nameEn: 'Buddhist Votive Stele',
    era: 'Western Wei朝 (A.D. 535–557), dated A.D. 551',
    region: '中国艺术藏品',
    category: '宗教礼器',
    material: 'Stone',
    dimensions: { height: 339.0, width: 99.0, depth: 21.6 },
    description: '佛教 stone tablets known as votive steles were commissioned by pious individuals and families, and erected in 寺庙 courtyards and other public spaces. The horizontal registers on this stele illustrate scenes from the life of the Buddha and from sacred texts. The upper pair of niches on this side depicts the death of the Buddha (right) and preparations for his cremation (left). On the opposite side, the primary scene represents the Buddha preaching the Lotus Sutra, a major scripture transmitted from India. The niches above show the Buddha flanked by monks and bodhisattvas (enlightened beings). Surrounding carvings portray ascetics, guardians, protective lions, heavenly musicians, and priests. Inscribed around the lower portion are the names of donors who commissioned this stele to commemorate their ancestors. The most important of these donors appear as standardized figures with parasols held aloft by their attendants. By commissioning such tablets, pious devotees hoped to gain spiritual benefits for themselves and their families.',
    history: 'Buddhist stone tablets known as votive steles were commissioned by pious individuals and families, and erected in temple courtyards and other public spaces。来源: Gift of The Orientals',
