    material: 'Buff陶器镶嵌多色与描金',
    dimensions: { height: 96.5, width: 96.5 },
    description: '陶瓷 figures made for burial in the tombs of princes and officials vividly evoke aspects of the elite life of China\'s expansive and multicultural Tang 朝代 (618-907). This armored guardian of haughty, impenetrable expression stands on a rocky plinth and was probably stationed close to the burial chamber to repel potential evil. One hand turns down in a clenched fist and the other turns upward with an outstretched finger, suggesting that both hands once brandished a weapon, now lost. His multilayered parade armor combines a helmet with upturned earflaps; neck and shoulder guards; scalloped breast and backplates secured by knotted ropes over a tunic with pleated hem; flared elbow cuffs over long, tight sleeves; and protective leggings under a sweeping skirt. The elements of this elaborate uniform were meticulously modeled in clay before firing and richly embellished with colors and 金 颜料 afterward.Because these so-called "cold pigments" are more vulnerable to deterioration than fired glazes, only traces of the most detailed patterns survive. These combine curled tendrils and scalloped floral scrolls on the armor, giving elegantly decorative flourishes to the armor of this impassive figure.Unlike most Tang figures that were formed in molds, this guardian appears to have been primarily hand-modeled, probably from coils of clay. It has survived remarkably intact; examination by museum conservators revealed only minimal restoration.',
    history: 'Ceramic figures made for burial in the tombs of princes and officials vividly evoke aspects of the elite life of China\'s expansive and multicultural Tang dynasty (618-907)。来源: Gift of Russell Tyson',
    images: ['https://www.artic.edu/iiif/2/dca595d5-1fce-2bfe-99c3-aa8f41657854/full/400,/0/default.jpg'],
    museum: '芝加哥艺术博物馆',
    location: '美国芝加哥',
    tags: ['中国艺术', '唐朝', '芝加哥艺术博物馆', '雕塑', '陶器'],
