    category: '装饰艺术',
    material: 'Cizhouware，炻器，slip-coated镶嵌釉下雕刻，incised，inlaid装饰',
    dimensions: { height: 9.6, width: 21.6, depth: 17.8 },
    description: 'With its sturdy 炻器 body and incised and carved decorations, this pillow is an example of Cizhou ware, a type of 陶瓷 crafted in northern China. While 陶瓷 pillows were initially perceived solely as items for burial, it is now believed they were also utilized in daily life. The 陶瓷 material served as an efficient cooling aid during hot summer days, while auspicious decorative motifs made these objects ideal gifts for special occasions. Symbolizing wealth, love, and feminine beauty, the motif of peonies frequently adorns Cizhou pillows, including this one here.',
