    description: 'The design of this mirror reflects principles of ancient 中国 cosmology that envisioned a circular universe enclosing a square earth. Within the border of the square are characters denoting the twelve animals of the 中国 zodiac. The marks resembling T, L, and V correspond to patterns on an instrument used by Han 朝代 diviners to foretell the future. This mirror was designed to place its owner at the center of the cosmos, a favorable position symbolically protected by the Animals of the Four Directions—the Green 龙 of the East, the Red 鸟 of the South, the White Tiger of the West, and the Black Warrior (tortoise and snake) of the North.',
