    dimensions: { height: 10.6, width: 5.7, depth: 0.5 },
    description: 'Artists of China\'s late 青铜 Age achieved both technical mastery and visual sophistication in elegant objects like this 玉 sheath, designed to fit a small blade. Its fluid contours and subtle surface modeling are remarkable because they were achieved by slowly grinding down, drilling, and polishing the stone.',
