    category: '绘画',
    material: 'Handscroll，墨纸',
    dimensions: { height: 1500.0, width: 41.3 },
    description: 'This fifty-foot composition reveals a “slit-view” perspective of 竹 growing along a stream. In single brushstrokes of varied tonality, leaves and stalks are depicted close up, cut off at top and bottom. Xia Chang executed this painting with great breadth and boldness as a gift for a friend who had planted a 竹 grove around his retirement villa.As it bends without breaking, 竹 evoked human values of resiliency and endurance for intellectual painters of premodern China. Xia’s dedicatory inscription on this scroll, describing the 竹 园林 as “washing away ordinary thought,” expresses their desire for retreat from the trials of official life. He had served the government in roles of calligrapher, draftsman, and administrative secretary before retiring for a decade in 1439, initially to care for his aged mother. This painting exhibits his style of angular rocks, 墨-washed shoreline, and fluent brushwork that matured during that period.',
    history: 'This fifty-foot composition reveals a “slit-view” perspective of bamboo growing along a stream。来源: Kate S. Buckingham Endowment Fund',
