    dimensions: { height: 38.7, width: 38.7 },
    description: 'Many scholars suggest that this distinctive Tang form may have been inspired by earlier, Hellenistic 陶瓷 and 玻璃 vessels deriving from the Greek amphora. If so, 中国 artisans thoroughly transformed that ancient shape: They created a high-shouldered silhouette with a slender neck, which is gracefully framed by curved handles, whose 龙 heads bite the cupped mouth-rim in their open jaws.This vessel displays a fluid "three-color" 釉, named after the archetypical combination of bright green, 琥珀, and white (transparent) lead-rich glazes colored with carefully measured recipes of metallic oxides. The green derives from 铜 and the 琥珀 from 铁.',
