    dimensions: { height: 24.1, width: 20.4, depth: 12.2 },
    description: 'The flat sides of this canteen-shaped container depict a youthful dancer and a musician who perform above a pair of romping lions. In their costumes and facial features, these performers resemble figures depicted in ancient Hellenistic art. The clarity of their features is partially obscured by a thickly applied 釉, as well as by the dense background of undulating foliage, floral heads, and grapevines. Some of these designs clearly derive from Central Asian metalwork. They may have been transmitted to China as decorative motifs on imported objects or alternatively, as background patterns on 佛教 images that were brought to China or created in China from Central Asian prototypes.',
