    dimensions: { height: 39.5, width: 24.0, depth: 21.5 },
    description: 'As burial practices filtered down from the Han aristocracy to officials and landowners, tomb models related to farming, an honored occupation, became increasingly popular. The granary, used to store millet, barley, and wheat, was depicted either as a jar or as a small building. The two-story granary found in southern 中国 tombs of the Western Han 朝代 (206 B.C.-A.D. 9) was a 木 or 陶瓷 model elevated on stilts. By the Eastern Han 朝代, this rectangular structure had spread to northern China and was raised on legs that were formed as crouching bears, a convention common to Han art. The inscription painted on the door of this granary states that it was made for the tomb of a local official.',
    history: 'As burial practices filtered down from the Han aristocracy to officials and landowners, tomb models related to farming, an honored occupation, became increasingly popular。来源: Lucy Maud Buckingham Collection',
