    id: '40558',
    name: 'Tea Drinking Under the Wutong Tree',
    nameEn: 'Tea Drinking Under the Wutong Tree',
    era: '明朝 (1369–1644年)',
    region: '中国绘画',
    category: '绘画',
    material: 'Handscroll，墨与slightcolor纸',
    dimensions: { height: 332.8, width: 23.4 },
    description: 'Generations of 中国 intellectuals and 佛教 monks honed the practice of tea tasting into a high art form. The "竹 stove" —a carrying case that contained a 陶瓷 kettle used for heating water—was central to the process of tea preparation. This ingenious device, fanned by a servant in the center of this painting, was the subject of a poem by Wu Kuan (1435-1504), a close friend of Tang Yin. In this composition, Wu appears on a low platform with a teapot and a scroll by his side. He shared the tea ceremony with a 佛教 monk, while another servant draws fresh water from a nearby stream.Five years after Wu Kuan\'s death, Tang Yin executed this delicate vignette in the writer\'s memory. The first colophon was written by Zhu Yunming (1461-1527), a famous poet and calligrapher who exchanged tea-related verses with Mr. Wu. Such commemorative paintings provide poignant records of 中国 intellectual and cultured society.',
