    id: '33997',
    name: 'Section of a Buddhist 塔',
    nameEn: 'Section of a Buddhist Pagoda',
    era: '唐朝 (618–907年)',
    region: '中国艺术藏品',
    category: '建筑残件',
    material: 'Limestone',
    dimensions: { height: 66.1, width: 43.2, depth: 25.4 },
    description: 'These two stone slabs originally formed the first story of a miniature 佛教 pagoda, which was elevated on a tiered base. Many such pagodas, usually standing seven or nine stories tall, are preserved from the eighth century in northern China.Now separated for display, these slabs were once tightly aligned to form one chamber whose interior was visible only though a canopied doorway cut into the front slab. Dynamic guardians, flying apsaras (heavenly beings), writhing dragons, and an ogre mask protect this doorway, which opens into a sacred space. The Buddha, seated in the center, is flanked by two bodhisattvas (compassionate saintly beings) holding lotus flowers. The bodhisattvas\' fluid postures, which echo those of sensual images from contemporary Indian art, distinguish many 佛教 sculptures of early-eighth-century China.A long inscription, carved into the left side of both slabs, states that the family of Jia Heida commissioned this pagoda in honorable devotion to his deceased parents. Replete with 佛教 metaphors and allusions to the Buddha s life, this text opens with a bleak perspective on the physical world and then praises both 佛教 teachings of spiritual redemption and secular values of 中国 filial devotion. The inscription closes with a prayer extolling 佛教 principles.The back of the rear slab is incised with images of two brothers, the bodhisattvas of medicine, who vow to heal the sick. The elder brother (left) holds a bowl containing a lotus 花, which symbolizes medicine; the younger brother (right) joins his hands in prayer. A small figure in the lower-left corner, who reaches out with one arm, as if pleading for medicine, may represent a faithful devotee. Inscriptions along the far-left and far-right edges identify the patron of these images as Konghui, a 佛教 nun. Inscriptions to the left of both brothers offer praise to the bodhisattvas.',
    history: 'These two stone slabs originally formed the first story of a miniature Buddhist pagoda, which was elevated on a tiered base。来源: Lucy Maud Buckingham Collection',
    images: ['https://www.artic.edu/iiif/2/6f5fa380-52da-965b-cc60-6baa129a18d6/full/400,/0/default.jpg'],
