    description: 'These triangular sculptures originally fit under the pitched roof of a burial chamber constructed of clay bricks. The position of similar panels discovered intact suggests that they originally formed two ends of a pediment that divided a chamber in half.The panels are carved and painted to depict winged figures mounted on dragons striding over hills or waves. In Han mythology, such beings are described as immortals (xian). Having achieved eternal life, these immortals were endowed with the power to fly and roamed freely about the universe. The depiction of these remarkable beings in tombs reflects a widespread belief that the soul of the deceased could leave its earth-bound existence, ascend to heaven, and become an immortal. The ascent of the soul to the realm of the immortals is a major theme in Han art.',
    history: 'These triangular sculptures originally fit under the pitched roof of a burial chamber constructed of clay bricks。来源: Gift of Mrs. Gordon Palmer',
    images: ['https://www.artic.edu/iiif/2/1447f7fa-cf7a-d30e-a7f0-6465640f6fe5/full/400,/0/default.jpg'],
    museum: '芝加哥艺术博物馆',
    location: '美国芝加哥',
