    dimensions: { height: 29.3, width: 13.6 },
    description: 'This type of vase with pouring spout and tubelike mouth at the shoulder has served several roles in 佛教 ritual: to purify a sacred space, to invoke a deity, or to anoint a worshipper. Created in 青铜 as well as several types of 炻器, these vessels originated in India and spread throughout East and Southeast Asia. In 中国 佛教 art, the kundika appears primarily as an attribute of the bodhisattva Guanyin (Sanskrit: Avalokitesvara). This 陶瓷 example may have been made primarily for burial.',
    history: 'This type of vase with pouring spout and tubelike mouth at the shoulder has served several roles in Buddhist ritual: to purify a sacred space, to invoke a deity, or to anoint a worshipper。来源: Gift of Mr. Russell Tyson',
