    material: 'Handscroll，墨与彩丝',
    dimensions: { height: 184.2, width: 41.9 },
    description: 'This all-female ensemble is an 皇家 or aristocratic orchestra. Singly or in pairs, the musicians play the large drum, clapper, oboe, vertical flute, transverse flute, hourglass drum, mouth organ, gong-chime, long zither, angular harp, and lute. Such instruments accurately represent those played by the mid- Tang 朝代 (eighth century), as known today from surviving artifacts and textural descriptions of the 皇家 Conservatory of Music. The audience for this concert strikingly resembles 宫廷 figures depicted in The Night Revels of Han Xizai, a painting in the 宫殿 Museum, 北京, attributed to the tenth century painter Gu Hongzhong. Gu Hongzhong was a contemporary of Zhou Wenju, to whom this handscroll was originally ascribed. The artist responsible for this fifteenth-century painting apparently drew upon a number of earlier artistic models, creating a composite image that recalled the work of past centuries.',
