    dimensions: { height: 15.9, width: 13.3, depth: 5.7 },
    description: 'Animal-shaped vessels are the rarest of all Shang ritual bronzes. This creature is a fascinating blend of alert poise and solemn dignity. Whereas the scaled pattern on the neck and tail of this 鸟 suggests feathers, other details are fantastic rather than anatomical. A 龙 in profile and a coiled serpent embellish each wing; monster masks crown the head as well as the removable lid on the 鸟\'s back.',
