    material: '青铜',
    dimensions: { height: 17.0, width: 14.2 },
    description: 'Unlike most 青铜 vessels whose shapes were derived from prehistoric 陶瓷 forms, this type of rectangular container was invented by Shang 青铜 artisans. Each side features a pair of profile birds with long, trailing tailfeathers. The black material in sunken areas of this design contains carbon. This filler is common to many Shang bronzes and seems to have been deliberately applied after casting in order to emphasize the surface decoration.',
