    dimensions: { height: 22.6, width: 17.5 },
    description: 'Often referred to as “boshan lu,” or hill censer, this incense burner features a conical cover shaped like miniaturized peaks, evoking the mountainous isles where the immortals reside. When incense is burnt in the step cup, fragrant smoke emanates from the openwork on the cover, animating the sacred mountains and transporting the beholder into a realm of transcendence. Covered with a green lead 釉, this pottery incense burner mimics similar objects that are commonly made in 青铜. The clay material suggests that the object might have been specifically made for a funerary context.',
