    dimensions: { height: 51.6, width: 33.5, depth: 11.5 },
    description: 'Burial models attest to the prevalence of multistoried buildings in early 皇家 China. This two-story structure, simply constructed of clay slabs, has a tile roof and an openwork balcony supported by brackets. Such realistic details are modified by imaginative "squatting-bear" feet. This model may depict a granary, or it may have been assembled with other clay structures to form a residential compound.',
