    material: 'Yixing炻器',
    dimensions: { height: 5.0, width: 8.3, depth: 7.3 },
    description: 'The body of this cup is crafted to resemble a lotus leaf, which gracefully rests upon feet in the shape of lotus pods. Ingeniously, the stems of these pods extend from the cup’s base to its side, forming an artful yet functional handle. The surface of the cup is embellished with delicately carved patterns, which contribute to the overall sense of realism while showcasing the luscious color and texture of the Yixing 炻器. Bearing the seal of Chen Mingyuan, a renowned potter of Yixing 炻器 active in the Kangxi period, this lotus-shaped cup exemplifies the artist’s celebrated talent for transforming clay into enchanting, lifelike wonders.',
    history: 'The body of this cup is crafted to resemble a lotus leaf, which gracefully rests upon feet in the shape of lotus pods。来源: Bequest of Russell Tyson',
