    dimensions: { height: 18.6, width: 33.3, depth: 21.0 },
    description: 'The lid and basin of this grain vessel are virtually identical in form; with the lid inverted, both pieces could be used as serving dishes. Its large lug handles are cast as vestiges of 龙 heads with rolled snouts; smaller heads are applied to the lid. The surface design consists of flat, tessellated planes composed of rectangular units of tightly interlaced ribbons. This restrained pattern reflects a new interest in finely textured grid patterns that transformed 青铜 design in the sixth century B.C. The blue (azurite) and green (孔雀石) patina is 铜 corrosion, formed over centuries of burial underground.The form of this vessel was originally based on a 竹 prototype, whose function was to hold grain, perhaps rice.',
