    id: '96627',
    name: 'The Wangchuan Villa 網川圖',
    nameEn: 'The Wangchuan Villa 網川圖',
    era: '金朝 (1115–1234年)',
    region: '中国绘画',
    category: '绘画',
    material: 'Handscroll，墨丝',
    dimensions: { height: 554.0, width: 26.3 },
    description: 'This painting depicts the private estate of Wang Wei (c. 699–761), a government statesman renowned as a poet, painter, calligrapher, and musician. Wang periodically retired to this countryside villa, which he described in a painting and in a poem of 20 quatrains. Although Wang’s original pictorial composition is not preserved, this early reinterpretation depicts the scenic spots vividly described in his poetry.',
    history: 'This painting depicts the private estate of Wang Wei (c。来源: Kate S. Buckingham Fund',
