    material: '青铜',
    dimensions: { height: 45.0, width: 24.8 },
    description: 'The 青铜 vessels produced with sophisticated casting techniques and intricate designs by 中国 artisans of the late Shang 朝代 (c. 1700-c. 1050 B.C.) are achievements unrivaled by any other 青铜 Age culture. For the ruling elite of ancient China, prestigious objects made of 青铜 signified supreme political power as well as devout spiritual beliefs and exalted social status. Foremost among these bronzes are vessels that were made for the preparation and offering of food, wine, and water in ceremonial banquets conducted to seek and repay divine ancestral goodwill. Ancient 中国 wine was fermented from grain rather than fruit and, like beer, is best described as a type of millet ale.This square-shouldered jar for wine storage is animated by a menagerie of imaginary creatures that have been intricately cast onto the surface in several levels of relief. The most prominent of these is a horned ogre mask (later known as a taotie), whose significance remains one of the great enigmas of early 中国 art. Here the taotie, inverted across the roof-like lid, recurs along the body within pendant triangular blades, each of which also contains a wide-eyed cicada at its tip. The cicada is found often on 中国 bronzes, perhaps because its extraordinarily long life cycle carried associations of regeneration. Confronted pairs of jaunty, stylized birds encircle the neck of the vessel, with similarly disposed dragons—each with down-curved head plume and up-curved tail around the widest part of the body. Birds and dragons are separated by a shoulder band of whorl circles, nose-diving dragons, and four fully sculpted bovine heads, two purely decorative and two surmounting lug handles. Two more such handles were cast on below to facilitate lifting. Compact, sharply cast spirals covering both the relief-cast taotie, dragons, and birds, and their receding background impart a shimmering effect to the surface, now covered with thin layers of cuprite red, 孔雀石 green, and azurite blue patina.',
    history: 'The bronze vessels produced with sophisticated casting techniques and intricate designs by Chinese artisans of the late Shang dynasty (c。来源: Lucy Maud Buckingham Collection',
    images: ['https://www.artic.edu/iiif/2/79b62d90-fa78-2c7f-b4a5-da75de63795a/full/400,/0/default.jpg'],
    museum: '芝加哥艺术博物馆',
    location: '美国芝加哥',
    tags: ['汉朝', '青铜', '宗教礼器', '中国艺术', '芝加哥艺术博物馆'],
