    category: '宗教礼器',
    material: '青铜',
    dimensions: { height: 34.8, width: 19.9 },
    description: 'Several types of chime bells were cast toward the end of China\'s 青铜 Age and were probably played together in concert. Smallest among these were niuzhong, which had concave rims. Niuzhong were cast in graduated sizes, assembled as a set (often of nine), and suspended from a horizontal beam in order of size. Each bell was designed to emit two distinct tones: one from striking the center of the lower panel, another from striking either corner. The mask centered on the striking panel of this bell is an abstraction of ferocious monster designs seen on earlier 青铜 vessels.',
    history: 'Several types of chime bells were cast toward the end of China\'s Bronze Age and were probably played together in concert。来源: Samuel M. Nickerson Endowment',
