    region: '中国艺术藏品',
    category: '宗教礼器',
    material: '玉',
    dimensions: { height: 19.6, width: 4.1, depth: 0.3 },
    description: 'The earliest archaeological finds of 丝 in China comprise very small fragments of fabric that are datable to the 4th and 3rd millennia B.C. Silks with woven patterns are rarely preserved but can be documented about one thousand years later, primarily through ghost-like imprints on 玉 implements as well as 青铜 vessels and weapons. Before burial, these prestigious ceremonial objects were evidently wrapped in fragile but fugitive 丝 fabrics.Preserved near the edge of this 玉 blade is a three-dimensional pseudomorph (“false form”) of a squared, tightly woven pattern, whose organic material has completely disintegrated and been replaced by minerals that duplicate the original 织物 structure. Under high magnification, this pattern displays a slight “Z” twist in the original filament thread, as characteristic of reeled 丝 that is simply woven (“平纹.”).Such indirect but clearly preserved evidence of Shang 朝代 丝 is extraordinarily rare. The collective expertise of the Art Institute’s conservation scientists and scholars of 中国 织物 history and technology have facilitated the identification of the material seen here.',
    history: 'The earliest archaeological finds of silk in China comprise very small fragments of fabric that are datable to the 4th and 3rd millennia B。来源: Edward and Louise B. Sonnenschein Collection',
