    name: 'Bathing of the 佛像 Festival',
    nameEn: 'Bathing of the Buddha Festival',
    era: '清朝 (1833)',
    region: '中国绘画',
    category: '绘画',
    material: 'Hangingscroll，墨与color丝',
    dimensions: { height: 108.9, width: 54.2 },
    description: 'This affable and remarkably zany cast of characters plays upon the festive atmosphere of an annual celebration held to commemorate the birth of the historical Buddha and his first shower by water-bearing dragons. Some of the disciples pictured flaunt pseudo-religious “miracles”: one opens his stomach to reveal the Buddha nature within and another magically creates a 寺庙 in mid-air. Other disciples nonchalantly engage on superficially mundane activities that allude to 佛教 conduct, such as mending clothes and reading sutras. A 狮, elephant, tiger, 龙, and 凤 are also in attendance; some serve as traditional vehicles of 佛教 deities, whereas others are more generally auspicious. Together, these personalities exude the vitality of a secularized but nonetheless sincere faith.',
