    material: 'Multi-blockwoodcutprint，water-soluble墨纸',
    dimensions: { height: 55.0, width: 39.8 },
    description: 'Woodblock printing on 纸 emerged in China around the seventh century as a way to preserve and copy 佛教 texts. Since that time, printmakers in East Asia have refined the technique by experimenting with color, size, and ways of bringing the 墨 and 纸 into contact with the block.Today, 中国 artists employ this time-honored medium to depict everything from landscapes to abstract forms. They also use different types of pigments to create varying degrees of opacity. This work comes from a portfolio that was commissioned in 1999 by the Muban Foundation in London to recognize the achievements of 中国 printmakers. This work demonstrates the woodblock print’s potential to connect the visual worlds of traditional and contemporary China.',
