    category: '装饰艺术',
    material: '瓷彩绘青花',
    dimensions: { height: 34.1, width: 5.5 },
    description: 'The design of musicians in the center of this dish is based on a print of a French “costume party” designed by French engravers. One possible source is the engraving titled Symphonie du Tympanum, du Luth et de la Flut d’Allemagne [Symphony of Dulcimer, Lute, and German Flute] by Nicholas Bonnart (1646-1718) and Robert Bonnart (1652-after 1686). 中国 porcelains decorated with such images reflected prevailing European fashion for masquerades and were generally commissioned for export to France, Italy, and Holland. As characteristic of many export wares ordered and shipped abroad by maritime companies and private traders, the panels of 中国 landscape encircling this French image create a truly multicultural composition.Although this dish was most likely intended for a French or other European client, the introduction of European aristocratic culture to China may also have piqued the interest of wealthy 中国 consumers in such romantically exotic designs.',
