    material: 'Colorwoodblockprint，surimono',
    dimensions: { height: 27.2, width: 18.5 },
    description: 'This print is a finely produced summer scene with a tangerine and nuts on embossed chrysanthemum-design 纸. The upper-left edge shows a piece of 纸 from the back, cleverly indicating the 纸 on which the objects were placed.The 纸 (with its characters in reverse) describes the biography of the 中国 hero Baili Xi, who was an influential prime minister of the state of Qin during the Spring and Autumn Period in ancient China. With the guidance of Baili, the Qin state was able to wage war and make peace with its neighbors, becoming the greatest power in the west. As on who combined learning and statesmanship, Baili thus became a hero for the literati of the Far East.',
