    dimensions: { height: 94.0, width: 94.0 },
    description: 'This clay figure depicting the evil-quelling guardian king is one of a pair. Images of such guardian kings, or Tianwang, have appeared both in and beyond China. In Indian mythology, these deities were believed to watch over the four directional quarters of the universe. Devotees of Buddhism adopted and popularized guardian kings throughout Central and East Asia. In Tang-朝代 China, images of these guardian kings, seen as embodiments of cosmic power, were installed to defend both secular and religious sites. Monumental images of stone or 木 were created for 佛教 temples. Smaller examples like this one were made of clay and buried in tombs to protect the deceased.',
