    dimensions: { height: 17.8, width: 19.4, depth: 27.3 },
    description: 'This humble-looking burial model illustrates two notable inventions in engineering and architecture that were in used widely during the Han 朝代. The rotary mill, worked by a pedal-operated hammer, was used to prepare grain for flour. The shed that encloses it has a deeply overhanging tile roof supported by a 木 column with projecting bracket arms. This type of bracketing, which transferred the weight of the roof to the column, became an increasingly important feature of later 中国 buildings.',
