    description: 'An old peasant returns from gathering the two bundles of horsetail rushes, which hang from a pole across his shoulder. Of the various poems about gathering rushes in the old anthologies, it is thought that Hokusai had in mind this poem from a 1303 collection:When I was cutting horsetailsThe autumn moon appearedShining through the treesOn Mount Sonahara.(Translated by Matthi Forrer)In this series of ten prints, the relevant poem was not included in the design. Instead, the artist challenged the Edo audience’s love of puzzles. Viewers enjoyed determining the source of a poem and its author.',
