    description: 'This 瓷 jar is decorated with images of The Four Accomplishments – qin (music), qi (the game of Go), shu (calligraphy), and hua (painting). In ancient China, mastery of these elegant skills was deemed essential for the ideal scholarly gentleman to signify sophistication and education. Consequently, motifs of The Four Accomplishments frequently appear in paintings and on decorative objects. Notably, this jar showcases women partaking in these scholarly pursuits that were traditionally associated with men, likely reflecting the rise of learned women during the Ming 朝代.',
    history: 'This porcelain jar is decorated with images of The Four Accomplishments –  qin (music), qi (the game of Go), shu (calligraphy), and hua (painting)。来源: Bequest of Russell Tyson',
