    dimensions: { height: 23.0, width: 17.5 },
    description: 'A monster mask (taotie) spreads boldly across this vessel, conforming to its bulging contour. While showing some stylistic features of slightly earlier manufacture, this vessel\'s heavy handles and the spiny dragons beneath the mouth rim are characteristic of bronzes of the early Western Zhou 朝代 (c. 1050-771 B.C.).The cruciform emblem enclosing the top character of the inscription is read ya. This emblem is thought to bear some relation to family names, although its exact meaning remains problematic.',
