    material: '青铜inlaid镶嵌金',
    dimensions: { height: 8.2, width: 8.2 },
    description: 'This small bell was designed with a clapper of 青铜 or bone (now lost) that was suspended from the short, hollow shank. It may have been used as a handbell to convey signals in military maneuvers. Much of its finely cast decoration—intertwined snakes and densely textured curls—is now camouflaged by surface corrosion. Traces of delicate 金-wire scrollwork are still visible near the rim. A diamond-like pattern with curvilinear motifs decorates the interior.',
