    name: 'Dream Journey to Rivers and Mountains',
    nameEn: 'Dream Journey to Rivers and Mountains',
    era: '清朝 (1644–1912年)',
    region: '中国绘画',
    category: '绘画',
    material: 'Handscroll，墨与soft彩纸',
    dimensions: { height: 282.0, width: 19.7 },
    description: 'In 1649, the former Ming 朝代 official Cheng Zhengkui emerged from retirement in south China to serve the new Manchu Qing 宫廷 in 北京. Thereafter, he resolved to paint and present as gifts to his fellow officials an ambitious series of more than one hundred scrolls under the title Dream Journey Among Rivers and Mountains. “Dream Journey,” literally “to travel while reclining,” suggests a tour that is purely visionary. This work is likely one of nearly forty scrolls that reportedly survive from the series. Although painted in 北京, Cheng’s imagery clearly depicts the low-lying hills, valleys, rivers, and waterfalls distinctive to south China, where intellectuals were relatively isolated from the new, alien regime. His tranquil style integrates subtle elements of earlier masters.',
    history: 'In 1649, the former Ming dynasty official Cheng Zhengkui emerged from retirement in south China to serve the new Manchu Qing court in Beijing。来源: W. L. Mead Fund',
