    material: '玉',
    dimensions: { height: 9.0, width: 8.1, depth: 2.2 },
    description: '中国 scholars commissioned exquisitely crafted sculptures to decorate the desks of their private studies. The upper corner of this miniature 山 cave is incised with an inscription datable to the reign of the Qianlong 皇帝 (r. 1736-1795). However, it is likely that this inscription was added later. The artistic style of the sculpture suggests that it was created one century earlier than the inscription. Carved to depict a 佛教 monk peacefully meditating in a grotto, the sculpture may have expressed the owner’s penchant for aesthetic and spiritual retreat during a time of political instability.',
