    dimensions: { height: 27.8, width: 23.2 },
    description: 'During the Han 朝代, economic stability and growth allowed officials and landowners to afford burial goods like aristocratic families could. Clay replicas of costly 青铜 and 漆 vessels also met the wider demand from middle-income patrons for tomb furnishings. This cauldron, modeled after a common 青铜 shape, has a lid that depicts a sinuous 龙—a design commonly found on lacquerware.',
