    era: '清朝 (1644–1911年)',
    region: '中国艺术藏品',
    category: '容器',
    material: '瓷镶嵌紫flambé釉',
    dimensions: { height: 33.0, width: 22.2 },
    description: 'This vase’s rich 釉 was created when a potter fired it in a kiln with restricted oxygen at a high temperature. The 铜 oxides in the 釉 transformed unpredictably into streaks of crimson, violet, and blue to create what is known as “flambé 釉.” Potters carefully manipulated kiln conditions in this process, called reduction firing, yet embraced the chance effects that gave each piece its unique, flame-like character. These striking results captivated European collectors, and ceramicists such as French artist Taxile Doat sought to reproduce the fluid, iridescent effects in their own work in the 18th and 19th centuries.',
    history: 'This vase’s rich glaze was created when a potter fired it in a kiln with restricted oxygen at a high temperature。来源: Lucy Maud Buckingham Collection',
