    category: '装饰艺术',
    material: '青铜',
    dimensions: { height: 20.6, width: 0.6 },
    description: 'Mirrors of the Han 朝代 were designed to procure blessings of longevity for the living and to guide the soul of the deceased toward immortal bliss. The images cast on the back of this mirror figured prominently in the quest for immortality that pervaded Han China. Two venerated deities that were later incorporated into the 道教 pantheon—the Queen Mother of the West (Xi Wang Mu) and the King Father of the East (Dong Wang Kong)—are seated opposite the central knob. Each is attended by immortals, identified by their whisks. Horse-drawn chariots may be interpreted as vehicles to escort the soul on its journey between this world and the next.',
