    category: '容器',
    material: '青铜镶嵌铜inlay',
    dimensions: { height: 25.4, width: 21.0 },
    description: 'Whereas this type of water ewer is found together with wine vessels in tombs of the Shang period, it typically appears with a shallow water basin (pan) in Zhou tombs. This change in burial context suggests a change in function—from a vessel used to dilute wine to one used to pour ablutions. In this imaginative, finely cast example, various creatures assume different parts: 鸟-men (or men with birdlike headdresses) form the legs; a 鸟\'s head acts as the spout; and on the lid, a small monkey grasps a chain linked to a feline animal whose broadly arched back forms the handle.',
