    id: '13954',
    name: 'Visiting Dai Kui on a Snowy Night 雪夜訪戴圖',
    nameEn: 'Visiting Dai Kui on a Snowy Night 雪夜訪戴圖',
    era: '明朝 (1368–1644年)',
    region: '中国绘画',
    category: '绘画',
    material: 'Hangingscroll，墨与彩丝',
    dimensions: { height: 195.6, width: 101.6 },
    description: 'This scene depicts the legendary story of Wang Huizhi (d. 388), the eccentric son of one of China’s most renowned calligraphers. As the fifth-century text New Account of Tales of the World (Shishuo xinyu) describes, Wang awoke in the midst of a snowy night and, inspired by a 玻璃 of wine, recalled the poem “Summons to a Retired Gentleman.” He then impulsively set out in a small boat to visit his reclusive friend Dai Kui. Upon arriving at Dai’s gate, however, Wang left without entering. Asked to explain his irrational behavior, he replied, “I originally went on the strength of an impulse, and when the impulse was spent, I turned back” (translated by Richard Mather). Wang appears here huddled in his boat, which is paddled by an attendant clothed in a straw raincoat.One or more large-scale compositions like this were typically commissioned for display in the grand reception halls of wealthy merchants and government officials. Encumbered by their urban lifestyles, these men typically idealized bucolic and often eccentric characters like the recluse portrayed here. This painting is part of the same set as Watching the Waterfall.',
    history: 'This scene depicts the legendary story of Wang Huizhi (d。来源: R. A. Waller Fund',
