    dimensions: { height: 22.0, width: 48.9, depth: 10.2 },
    description: 'This is one of sixteen hollow 青铜 fittings in the museum\'s collection that together comprise rectangular, L-shaped, and cylindrical pieces. In 1973, fittings of similar shape and design were excavated from the site of a 宫殿 of the 7世纪 B.C. in modern-day Fengxiang, Shaanxi province in north China. Most show tightly interlaced surface patterns like those cast in this piece. Archaeologists have conjectured that these fittings, some of which preserve traces of 木, originally served as collars and sleeves that had been socketed over a framework of timber columns and tie beams embedded into the earthen walls. Some of these pieces may originally have been stuffed with 丝 to tighten them.',
