    category: '容器',
    material: '陶器镶嵌模制装饰与three-color(sancai)leadglazes',
    dimensions: { height: 32.2, width: 13.0 },
    description: 'The 珍珠-shaped body, cartouche-like medallions, and leafy details on the handle of this vessel were all inspired by silverware from the ancient Persian (Iranian) city-state of Sogdiana. Sogdiana was an important stop along the 丝 Road, a network of trade routes that connected China to Europe and Africa through Central Asia. Crowned by the head of a 凤, this ewer’s flattened form was molded in two halves and then joined along vertical seams. When it was fired, lead glazes flowed freely over the relief decoration of a perched or dancing 凤 framed by floral scrolls. The opposite side depicts an archer mounted on a horse.',
