    nameEn: 'Lobed Dish with Overlapping Lotus Leaves',
    era: '唐朝 (618–907年)',
    region: '中国艺术藏品',
    category: '容器',
    material: 'Yueware，炻器镶嵌paleolive-绿釉与釉下incised装饰',
    dimensions: { height: 13.8, width: 2.5 },
    description: '',
    history: '来源: Bequest of Russell Tyson',
    images: ['https://www.artic.edu/iiif/2/e86b62c5-7a62-7084-afec-aaa900b9dd4b/full/400,/0/default.jpg'],
    museum: '芝加哥艺术博物馆',
    location: '美国芝加哥',
