    material: 'Lushanware，炻器镶嵌铁-棕与splashedmilky-蓝ashglazes',
    dimensions: { height: 46.3, width: 46.3 },
    description: 'This elegant jar exemplifies the 炻器 craftsmanship of the Lushan kiln, a center of 炻器 production during the Tang 朝代. Beneath the rolled lip, four handles that evoke the shape of stylized birds curve downward, directing the viewer’s gaze to the smooth, satiny surface. Covered with a captivating mottled brown "tea-dust" 釉 and embellished with bold, lively splashes of milky lavender, the jar displays a timeless beauty. The brown 釉 stops neatly with a clean sweep just above slightly flared foot, exposing the dense clay body tinged with a subtle orange hue from the firing process. Jars like this are recognized as innovative precursors to the renowned Song-朝代 Jun ware.',
    history: 'This elegant jar exemplifies the stoneware craftsmanship of the Lushan kiln, a center of stoneware production during the Tang Dynasty。来源: Robert A. Waller Fund',
