    id: '70003',
    name: 'Funerary 瓮 (Hunping)',
    nameEn: 'Funerary Urn (Hunping)',
    era: '金朝 (265–316年)',
    region: '中国艺术藏品',
    category: '宗教礼器',
    material: '炻器镶嵌olive-绿釉与模制与施加装饰',
    dimensions: { height: 48.7, width: 27.5 },
    description: 'This complex and imaginatively modeled vessel is known as an “urn of the soul,” a symbolic dwelling for the spirit of the deceased. A profusion of figures was molded and applied to its sealed lid, which takes the form of a multistory pavilion. In the balcony-like mouth-rim, a tortoise supports a large vertical tablet, a common form of memorial stone. The real and mythical creatures on the vessel—birds, monkeys, bears, dragons, kneeling figures, and immortals riding dragons—all follow the iconography of early 中国 funerary art. Intermingled with these images, however, are depictions of the Buddha, who is identified by his meditating posture, topknot, and halo. The marginal role of 佛教 art in this decorative scheme reflects the adoption of the alien Indian religion, as the 中国 then understood it, into a hospitable mélange of different spiritual beliefs. Additionally, this jar reflects a formative stage in the development of China’s renowned 青瓷 釉, which became more uniform in color and texture over subsequent centuries.',
    history: 'This complex and imaginatively modeled vessel is known as an “urn of the soul,” a symbolic dwelling for the spirit of the deceased。来源: Through prior bequests of Mary Hooker Dole and Grace Brown Palmer; through prior gifts of Josephine P. Albright in memory of Alice Higinbotham Patterson, and Mrs. Kent S. Clow; Russell Tyson, Robert C. Ross endowments',
    images: ['https://www.artic.edu/iiif/2/bf4060c6-8b68-d4f3-acb0-cfeaea86ad05/full/400,/0/default.jpg'],
