    category: '容器',
    material: 'Yaozhouware，炻器，雕刻与biscuit-fired',
    dimensions: { height: 11.6, width: 6.6 },
    description: 'After the eleventh century, the use of clay molds became increasingly common in the 陶瓷 production of northern China. Finely carved molds impressed intricate decorations on vessels’ surfaces before firing with both precision and speed, in order to meet the growing demands for 陶瓷 wares at the time. While molds have been excavated at various kiln sites in Shaanxi and Henan provinces, those from Yaozhou, such as this one, are believed to have produced some of the most exquisite molded designs on 陶瓷 wares during that period.',
