    id: '57678',
    name: 'Tripod Cylindrical 罐 (Lian or Zun) with Creatures Amid Hills, Bear-Shaped Feet',
    nameEn: 'Tripod Cylindrical Jar (Lian or Zun) with Creatures Amid Hills, Bear-Shaped Feet',
    era: '汉朝 (Eastern  (A.D. 25–220)',
    region: '中国艺术藏品',
    category: '容器',
    material: '陶器镶嵌lead绿釉',
    dimensions: { height: 24.8, width: 18.5 },
    description: 'Vessels like this are often called "hill jars" since many have conical covers shaped in rising peaks. "Squatting-bear" feet and monster-mask ring handles are common features. This jar has been mold-impressed in two relief bands depicting hills populated with real and imaginary creatures. Wispy elflike figures are associated with immortals (xian), who were thought to dwell in 山 paradises. Such relief designs provide intriguing evidence of early landscapes painted on more perishable 纸 and 丝.',
    history: 'Vessels like this are often called &quot;hill jars&quot; since many have conical covers shaped in rising peaks。来源: Gift of Bertha Palmer Thorne',
