    name: 'Ariwara no Narihira, from the series A True 镜 of Chinese and Japanese Poems',
    nameEn: 'Ariwara no Narihira, from the series A True Mirror of Chinese and Japanese Poems',
    era: '约1830',
    region: '中国艺术藏品',
    category: '版画',
    material: 'Colorwoodblockprint，nagaban',
    dimensions: { height: 50.3, width: 21.3 },
    description: 'This image appears to relate to a scene described in the ninety-fourth poem in the One Hundred Poems by One Hundred Poets series by Privy Councilor Masatsune; it is not clear why the poem has been attributed to the much more famous Narihira: From Mount Yoshino Blows a chill autumnal wind, In the deepening night. Cold the ancient hamlet is; Sounds of beating cloth I hear. (Translated by Clay MacCauley)',
    history: '来源: Clarence Buckingham Collection',
    images: ['https://www.artic.edu/iiif/2/8baa7644-4c15-5cc3-d709-cc2d4ffce0b7/full/400,/0/default.jpg'],
    museum: '芝加哥艺术博物馆',
