    era: '汉朝 (3-2世纪)',
    region: '中国艺术藏品',
    category: '装饰艺术',
    material: '青铜',
    dimensions: { height: 20.8, width: 20.8 },
    description: 'The mirror in ancient China, usually held by hand with a cord, was a thin 青铜 disk with one face polished to a reflective sheen. The backs of mirrors were cast with elegant and dynamic designs that often reflect then-contemporary 织物 designs. The ground of interlocking T\'s on this mirror is known from 织物 finds as well as from impressions of deteriorated fabrics preserved in the surface corrosion of bronzes. Superimposed on, and contrasting with, this rectangular ground are flowing 龙- and 鸟-headed figures reminiscent of those seen in 绣 designs. The interplay of lines and curves is characteristic of the decorative art of the third and second centuries B.C.',
    history: 'The mirror in ancient China, usually held by hand with a cord, was a thin bronze disk with one face polished to a reflective sheen。来源: Samuel M. Nickerson Fund',
