    category: '绘画',
    material: 'Hangingscroll，墨与color纸',
    dimensions: { height: 134.7, width: 50.2 },
    description: 'This relaxed portrait is of Du Jun, a 中国 scholar who lived from 1611 to 1687—so he survived a tumultuous time in 中国 history that saw the collapse of the Ming 朝代 in 1644 and its replacement by the Manchu-ruled Qing 朝代. The pine tree depicted here is a symbol of resistance as well as lofty ideals and alludes to his character. He was a respected figure in the city of 南京, his home for more than four decades.',
