    material: 'Limestone镶嵌微量polychromy',
    dimensions: { height: 88.3, width: 25.4, depth: 16.6 },
    description: 'Expressing serene dignity, these youthful monks stand erect, their eyes downcast and hands firmly joined in reverent prayer. Their long earlobes allude to earrings that were worn by the Buddha as a young Indian prince and to his rejection of material wealth. Characteristic of Sui 朝代 sculpture, the monks’ sharply defined facial features and the folds of their robes enhance the figures’ flat, understated modeling. Each of their robes was originally painted with rectangles of different colors, signifying the patchwork mantle worn by the Buddha and by pious monks who emulated his humble values. Only shadowy traces of these pigments are now evident.',
