    name: 'Parting at the Gate of the Capital',
    nameEn: 'Parting at the Gate of the Capital',
    era: '明朝 (1369–1644年)',
    region: '中国绘画',
    category: '绘画',
    material: 'Handscroll，墨与color纸',
    dimensions: { height: 461.1, width: 53.4 },
    description: 'This handscroll captures a goodbye. Along the riverbank, a boatman poised with paddle in hand stands tall in anticipation of launching. Nearby, scholars wearing black hats linger over their departure. Within the thatched pavilion, two servants diligently pack up the remains of a farewell party. In ancient China, a handscroll would be viewed by unrolling it in segments, one arm’s length at a time, from right to left. This handscroll would thus gradually reveal the travelers and the distant landscape, creating the effect of sending them off.',
