    description: 'The handled bucket is described in ancient texts as a vessel for carrying wine. This vessel\'s gently sagging profile is sparsely decorated—dragons with detached, hooked trunks are confined to narrow bands around the neck and lid. Contrasting with these abstract designs are more naturalistic rams\' heads at the neck and on the handles, which are sculpted in the round. Such realistic animals appeared as secondary motifs on Shang bronzes but became more prominent during the Western Zhou.Identical inscriptions are cast inside the bucket and lid: Zi Fu Geng [made for Father Geng of the Zi family]',
    history: 'The handled bucket is described in ancient texts as a vessel for carrying wine。来源: Lucy Maud Buckingham Collection',
    images: ['https://www.artic.edu/iiif/2/256302d0-37e0-f383-8123-c13e6ab8ddbb/full/400,/0/default.jpg'],
    museum: '芝加哥艺术博物馆',
    location: '美国芝加哥',
    tags: ['周朝', '青铜', '中国艺术', '容器', '芝加哥艺术博物馆'],
