    id: '21385',
    name: 'Container in the Form of a Bronze 罐 (Hu)',
    nameEn: 'Container in the Form of a Bronze Jar (Hu)',
    era: 'Warring States period, 475–公元前221年E',
    region: '中国艺术藏品',
    category: '容器',
    material: '陶器',
    dimensions: { height: 36.0, width: 21.6 },
    description: 'The shape of this container and the monster-mask (taotie) decoration on its sides closely imitate those of 青铜 vessels. The use of clay rather than the more costly 青铜 reveals the object’s function as mingqi or “spirit good,” an object that was made specifically for the funerary context. The animal imagery and geometric patterns on the vessel surface, however, are distinctive to objects made of clay. Tigers, fish, and birds—images drawn from land, water, and air—represent early attempts in 中国 art to portray the natural world. Similar ceramics have been excavated from tombs of the ancient State of Yan, in the region of modern-day 北京.',
    history: 'The shape of this container and the monster-mask (taotie) decoration on its sides closely imitate those of bronze vessels。来源: Bequest of Russell Tyson',
