    dimensions: { height: 315.0, width: 39.4 },
    description: 'Within Buddhism, a luohan is an enlightened being that typically possesses fantastical powers. The many luohans in this work are accompanied by both real and imaginary creatures as they clamber over inverted hills, float above clouds, and glide across swirling waters, occasionally pausing to meditate in a 竹 grove. Their profusion suggests that these sages are intended to depict the Daoism-inspired legend “Five Hundred Luohans Crossing the Sea,” which describes a multitude traveling to an immortal realm.',
