    material: 'Woodcutprinted镶嵌oil-basedinks',
    dimensions: { height: 81.5, width: 47.7 },
    description: 'In this delicately rendered print, a Tibetan woman observes three pandas drinking from a marsh. A pioneer in modern 中国 printmaking, Niu Wen was among the first 中国 artists to depict Tibetan people after the Communist conquest of Tibet in 1951. The artist’s signature style is evident in the meticulous, threadlike lines that define the vast grassland and the intricate patterns of the woman’s garment. In contrast, bold black shapes emphasize the pandas’ forms and the woman’s flowing coat, creating a striking balance of detail and depth.',
