    region: '中国雕塑',
    category: '雕塑',
    material: '木镶嵌微量多色pigments',
    dimensions: { height: 52.0, width: 10.3, depth: 5.3 },
    description: 'In Chu tombs, 木 sculptures of men and women were placed in compartments surrounding the coffin. Natural weathering has accentuated the elegant attenuation of these figures. Some were constructed with separate forearms and hands, now lost, that were tenoned into small holes in their sleeves.',
