    region: '中国艺术藏品',
    category: '容器',
    material: '青铜',
    dimensions: { height: 31.2, width: 17.5 },
    description: 'This elegantly dignified vessel displays the taut, slender profile and crisply cast surface decoration that distinguishes the finest bronzes made for late Shang royalty. Long tapered blades above a band of serpents encircle the wide, trumpet-mouthed neck. Monster masks (taotie) with angular horns surround the middle section. All motifs are organized in clearly defined quadrants, which are divided by striated flanges and reserved against a background of finely squared spirals.',
