    region: '中国艺术藏品',
    category: '装饰艺术',
    material: '青铜',
    dimensions: { height: 16.0, width: 16.0 },
    description: 'The mirror in ancient China, usually held by hand with a cord, was a thin 青铜 disk with one face polished to a reflective sheen. The backs of mirrors were cast with elegant and dynamic designs. Tight spirals and triangles that form the ground pattern of this mirror are distinctive to south-central and southern China. These fanciful configurations seem to have been inspired by painted lacquers and 绣 and woven textiles distinctive to that area, which was occupied by the Kingdom of Chu.',
