    dimensions: { height: 3.6, width: 12.6, depth: 10.6 },
    description: 'Eared cups with warming stands were probably used to heat sauces for meat. Each side of these warming stands is cast with one of the Animals of the Four Directions (si shen)—the Green 龙 of the East, the White Tiger of the West, the Black Warrior (tortoise and snake) of the North, and the Red 鸟 of the South. In Han art, the pervasive appearance of these symbolic animals reflects a desire to center the owner within the favorable influences of the universe.',
