    material: '雕刻cinnabar漆木',
    dimensions: { height: 32.4, width: 9.5 },
    description: 'This vessel plays upon a rebus: the words for “butterfly” and “gourd” together allude to the wish for innumerable generations of sons and grandsons. The image of fruit-bearing stems visually reinforces this ideal, which was highly valued in traditional 儒家 society. Butterflies with beautifully contoured wings flutter amid red, orange, and pale green gourds, melons, pumpkins, or squash. The lobed fruits are decorative rather than botanically specific; together, they grow from gracefully trailing stems with large palmette leaves and elegantly curled tendrils.',
    history: 'This vessel plays upon a rebus: the words for “butterfly” and “gourd” together allude to the wish for innumerable generations of sons and grandsons。来源: Gift of Mrs. Charles Fabens Kelley in memory of Charles Fabens Kelley',
