    id: '42242',
    name: 'Compound 花瓶 with Six Trumpet-Shaped Necks',
    nameEn: 'Compound Vase with Six Trumpet-Shaped Necks',
    era: '清朝 (1644–1911年)',
    region: '中国艺术藏品',
    category: '容器',
    material: 'Glazed炻器',
    dimensions: { height: 24.2, width: 18.5 },
    description: 'The unusual form of this vase is achieved by conjoining five identical long-neck bottles, with their mouths opening up into a shared cavity. Covered in a pale green 青瓷 釉, the surface of this 炻器 vessel evokes that of high-quality Longquan 青瓷, which reached its pinnacle during the Song 朝代. On the base of the center bottle, a Qianlong reign mark is inscribed in archaic seal characters. While pieces like this could occasionally serve as 花 vases, they were most likely crafted as unique showstoppers.',
