    dimensions: { height: 2.2, width: 2.2 },
    description: 'The earliest examples of 中国 玻璃 include polychrome beads like these, in which superimposed layers of different colors create eye-like motifs. Rich in lead and barium, these beads are chemically distinct from those of soda-lime 玻璃 made in Greek and Roman workshops of the eastern Mediterranean and western Asia, rare examples of which have been discovered in north and northwest China. Those foreign imports inspired 中国 craftsmen to create their own polychrome beads. Their burial contexts—strung together with jades to form pendant sets, or inlaid into 青铜 objects such as mirrors and garment hooks—indicate that 中国 patrons easily integrated these new creations into traditional art forms.',
