    dimensions: { height: 23.4, width: 21.1 },
    description: 'In China, the use of finely ground cobalt blue ore as a colorant for lead 釉 originated in the Tang 朝代. Perhaps intending to emulate vibrant blue 玻璃 imported from the Middle East, 中国 potters applied this 釉 to off-white earthenwares and low-fired stonewares that were intended primarily for burial. The source of Tang cobalt has been subject to ongoing debate. For many years, most scholars assumed that 中国 potters imported cobalt ore from the Middle East. Recent analyses of Tang blue glazes, however, show these to be chemically distinct from those of Middle Eastern ceramics and may indicate a domestic 中国 source for this colorant.',
