    id: '21662',
    name: 'Conical 碗 with Decoration of Three Leaves',
    nameEn: 'Conical Bowl with Decoration of Three Leaves',
    era: '宋朝 (1127–1279年)',
    region: '中国艺术藏品',
    category: '容器',
    material: 'Jizhouware，glazed炻器镶嵌kilntransmutations',
    dimensions: { height: 15.3, width: 4.9 },
    description: 'This tea bowl is a fine example of the renowned Jizhou ware, which is famous for the subtle leaf-shaped imprint against the dark 釉 on the object interior. This effect is believed to be achieved by placing real leaves covered in the 釉 mixture on the vessel surface before firing. The leaves would then be burnt away in the kiln, leaving behind their traces. Another hallmark of the Jizhou ware is the "tortoiseshell 釉," created by applying light-brown splashes on the darker surface in imitation of tortoiseshell. This pattern can also be observed on the interior of this tea bowl.',
    history: 'This tea bowl is a fine example of the renowned Jizhou ware, which is famous for the subtle leaf-shaped imprint against the dark glaze on the object interior。来源: Bequest of Russell Tyson',
